{"solution_py":""""Write a deterministic manifest for regular files below a root."""
from __future__ import annotations

import hashlib
import json
import stat
from pathlib import Path


def build_manifest(root: Path, output: Path) -> list[dict[str, object]]:
    """Hash regular files below *root* and write a canonical JSON manifest."""
    root_path = root.resolve()
    output_path = output.resolve()
    rows: list[dict[str, object]] = []

    for candidate in root_path.rglob("*"):
        try:
            relative = candidate.relative_to(root_path)
            if ".git" in relative.parts or candidate.name.endswith(".tmp"):
                continue
            if candidate.resolve() == output_path:
                continue
            if candidate.is_symlink() or not stat.S_ISREG(candidate.lstat().st_mode):
                continue

            digest = hashlib.sha256()
            with candidate.open("rb") as stream:
                for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                    digest.update(chunk)

            rows.append(
                {
                    "path": relative.as_posix(),
                    "sha256": digest.hexdigest(),
                }
            )
        except (FileNotFoundError, PermissionError):
            continue

    rows.sort(key=lambda row: str(row["path"]))
    content = json.dumps(rows, ensure_ascii=True, sort_keys=True, separators=(",", ":")) + "\n"
    with output.open("w", encoding="utf-8", newline="\n") as stream:
        stream.write(content)
    return rows
